            print(f"      {project_path}")

            for idx in project_indexes:
                total_indexes += 1
                type_icon = "📁" if idx["type"] == "cli" else "📄"
                print(f"      • {type_icon} {idx['name']} {idx['status']}")
                if idx["size_mb"] > 0:
