def _build_gitignore_parser(self, docs_dir: str):
    """Build gitignore parser using gitignore-parser library."""
    from gitignore_parser import parse_gitignore

    # Try to parse the root .gitignore
    gitignore_path = Path(docs_dir) / ".gitignore"

    if gitignore_path.exists():
        try:
            # gitignore-parser automatically handles all subdirectory .gitignore files!
            matches = parse_gitignore(str(gitignore_path))
            print(f"📋 Loaded .gitignore from {docs_dir} (includes all subdirectories)")
            return matches
        except Exception as e:
            print(f"Warning: Could not parse .gitignore: {e}")
    else:
        print("📋 No .gitignore found")

    # Fallback: basic pattern matching for essential files
    essential_patterns = {".git", ".DS_Store", "__pycache__", "node_modules", ".venv", "venv"}

    def basic_matches(file_path):
        path_parts = Path(file_path).parts
        return any(part in essential_patterns for part in path_parts)

    return basic_matches

def create_text_chunks(
    documents,
    chunk_size: int = 256,
    chunk_overlap: int = 128,
    use_ast_chunking: bool = False,
    ast_chunk_size: int = 512,
    ast_chunk_overlap: int = 64,
    code_file_extensions: Optional[list[str]] = None,
    ast_fallback_traditional: bool = True,
) -> list[dict[str, Any]]:
    """Create text chunks from documents with optional AST support for code files.

    Returns:
        List of dicts with {"text": str, "metadata": dict}
    """
    if not documents:
        logger.warning("No documents provided for chunking")
        return []

    local_code_extensions = CODE_EXTENSIONS.copy()
    if code_file_extensions:
        ext_mapping = {
            ".py": "python",
            ".java": "java",
            ".cs": "c_sharp",
            ".ts": "typescript",
            ".tsx": "typescript",
        }
        for ext in code_file_extensions:
            if ext.lower() not in local_code_extensions:
                if ext.lower() in ext_mapping:
                    local_code_extensions[ext.lower()] = ext_mapping[ext.lower()]
                else:
                    logger.warning(f"Unsupported extension {ext}, will use traditional chunking")

    all_chunks = []
    if use_ast_chunking:
        code_docs, text_docs = detect_code_files(documents, local_code_extensions)
        if code_docs:
            try:
                all_chunks.extend(
                    create_ast_chunks(
                        code_docs, max_chunk_size=ast_chunk_size, chunk_overlap=ast_chunk_overlap
                    )
                )
            except Exception as e:
                logger.error(f"AST chunking failed: {e}")
                if ast_fallback_traditional:
                    all_chunks.extend(
                        _traditional_chunks_as_dicts(code_docs, chunk_size, chunk_overlap)
                    )
                else:
                    raise
        if text_docs:
            all_chunks.extend(_traditional_chunks_as_dicts(text_docs, chunk_size, chunk_overlap))
    else:
        all_chunks = _traditional_chunks_as_dicts(documents, chunk_size, chunk_overlap)

    logger.info(f"Total chunks created: {len(all_chunks)}")

    # Note: Token truncation is now handled at embedding time with dynamic model limits
    # See get_model_token_limit() and truncate_to_token_limit() in embedding_compute.py
    return all_chunks

def extract_pdf_text_with_pymupdf(file_path: str) -> str | None:
    """Extract text from PDF using PyMuPDF for better quality."""
    try:
        import fitz  # PyMuPDF

        doc = fitz.open(file_path)
